const n=[{lessonId:1,lessonKey:"Bài 1",lessonTitleZh:"AI小语，你好！",lessonTitleFull:"Bài 1: AI小语，你好！",grammarPoints:[{id:"hsk1_b1_g1",num:1,title:"Cách chào hỏi",explanation:'Trong tiếng Trung, cách chào hỏi thông dụng nhất là ghép đối tượng được chào với từ "好" (hǎo - tốt, lành).',formula:`Công thức chung: 
[Đối tượng được chào] + 好 (hǎo)`,note:"Khi chào người lớn tuổi hoặc người cần tôn trọng, nên dùng 您好 (nín hǎo) thay vì 你好 (nǐ hǎo).",examples:[{rawZh:"- 你好 (nǐ hǎo)",zh:"你好",pinyin:"nǐ hǎo",vi:"Chào bạn"},{rawZh:"- 您好 (nín hǎo)",zh:"您好",pinyin:"nín hǎo",vi:"Chào ngài/ông/bà (kính trọng)"},{rawZh:"- 大家好 (dàjiā hǎo)",zh:"大家好",pinyin:"dàjiā hǎo",vi:"Chào mọi người"},{rawZh:"- 你们好 (nǐmen hǎo)",zh:"你们好",pinyin:"nǐmen hǎo",vi:"Chào các bạn"},{rawZh:"- 老师好 (lǎoshī hǎo)",zh:"老师好",pinyin:"lǎoshī hǎo",vi:"Chào thầy/cô"}],tables:null,exercises:null}]},{lessonId:2,lessonKey:"Bài 2",lessonTitleZh:"我叫李文",lessonTitleFull:"Bài 2: 我叫李文",grammarPoints:[{id:"hsk1_b2_g1",num:1,title:"Câu cơ bản: Chủ ngữ + Động từ + Tân ngữ (S + V + O)",explanation:"Đây là cấu trúc câu đơn giản nhất trong tiếng Trung để diễn đạt ai làm gì.",formula:"S + V + O",note:null,examples:[{rawZh:"我爱你。(Wǒ ài nǐ.)",zh:"我爱你。",pinyin:"Wǒ ài nǐ.",vi:"Tôi yêu bạn."},{rawZh:"他喝茶。(Tā hē chá.)",zh:"他喝茶。",pinyin:"Tā hē chá.",vi:"Anh ấy uống trà."}],tables:null,exercises:null},{id:"hsk1_b2_g2",num:2,title:"Trạng ngữ thời gian và địa điểm",explanation:"Trong tiếng Trung, trạng ngữ chỉ thời gian và địa điểm luôn đứng trước động từ vị ngữ, không bao giờ đứng cuối câu.",formula:"Thời gian + Chủ ngữ + Địa điểm + Động từ + Tân ngữ",note:null,examples:[{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."}],tables:null,exercises:null},{id:"hsk1_b2_g3",num:3,title:"Vị trí của phó từ (不 - không, 很 - rất)",explanation:"Phó từ dùng để bổ nghĩa cho động từ hoặc tính từ, vị trí luôn đứng trước động từ hoặc tính từ đó.",formula:"Chủ ngữ + Phó từ + Động từ/Tính từ",note:null,examples:[{rawZh:"他不喜欢。(Tā bù xǐhuan.)",zh:"他不喜欢。",pinyin:"Tā bù xǐhuan.",vi:"Anh ấy không thích."},{rawZh:"苹果很好。(Píngguǒ hěn hǎo.)",zh:"苹果很好。",pinyin:"Píngguǒ hěn hǎo.",vi:"Táo rất ngon/tốt."}],tables:null,exercises:null}]},{lessonId:3,lessonKey:"Bài 3",lessonTitleZh:"我是中国人",lessonTitleFull:"Bài 3: 我是中国人",grammarPoints:[{id:"hsk1_b3_g1",num:1,title:"Câu chữ “是”",explanation:"Câu chữ “是” (shì) được dùng để định danh, giới thiệu người hoặc sự vật (là...). Hình thức phủ định là “不是” (bú shì - không phải là).",formula:"S + (不)是 + O",note:null,examples:[{rawZh:"我不是中国人，我是越南人。(Wǒ bú shì Zhōngguó rén, wǒ shì Yuènán rén.)",zh:"我不是中国人，我是越南人。",pinyin:"Wǒ bú shì Zhōngguó rén, wǒ shì Yuènán rén.",vi:"Tôi không phải là người Trung Quốc, tôi là người Việt Nam."},{rawZh:"他是我的老师。(Tā shì wǒ de lǎoshī.)",zh:"他是我的老师。",pinyin:"Tā shì wǒ de lǎoshī.",vi:"Thầy ấy là giáo viên của tôi."}],tables:null,exercises:null},{id:"hsk1_b3_g2",num:2,title:"Trợ từ kết cấu “的”",explanation:"Trợ từ kết cấu “的” (de) được đặt giữa định ngữ và trung tâm ngữ để diễn đạt mối quan hệ sở hữu (của...).",formula:"Định ngữ + 的 + Trung tâm ngữ",note:"Trong trường hợp trước “的” (định ngữ) là đại từ nhân xưng, sau “的” (trung tâm ngữ) là từ chỉ quan hệ thân thuộc hoặc danh từ chỉ người, “的” có thể được lược bỏ để câu tự nhiên hơn.",examples:[{rawZh:"你的名字 (nǐ de míngzi)",zh:"你的名字",pinyin:"nǐ de míngzi",vi:"Tên của bạn"},{rawZh:"你的老师 (nǐ de lǎoshī)",zh:"你的老师",pinyin:"nǐ de lǎoshī",vi:"Thầy/cô giáo của bạn"},{rawZh:"我老师 (wǒ lǎoshī)",zh:"我老师",pinyin:"wǒ lǎoshī",vi:"Giáo viên của tôi (lược bỏ 的)"},{rawZh:"你同学 (nǐ tóngxué)",zh:"你同学",pinyin:"nǐ tóngxué",vi:"Bạn học của bạn (lược bỏ 的)"},{rawZh:"我学生 (wǒ xuésheng)",zh:"我学生",pinyin:"wǒ xuésheng",vi:"Học sinh của tôi (lược bỏ 的)"},{rawZh:"你妈妈 (nǐ māma)",zh:"你妈妈",pinyin:"nǐ māma",vi:"Mẹ của bạn (lược bỏ 的)"}],tables:null,exercises:null},{id:"hsk1_b3_g3",num:3,title:"Câu hỏi “có… (hay) không?” sử dụng từ “吗”",explanation:"Trợ từ nghi vấn “吗” (ma) đặt ở cuối câu trần thuật để tạo câu hỏi Có/Không (Yes/No Question).",formula:"S + V + O + 吗?",note:null,examples:[{rawZh:"你是中国人吗？(Nǐ shì Zhōngguó rén ma?)",zh:"你是中国人吗？",pinyin:"Nǐ shì Zhōngguó rén ma?",vi:"Bạn là người Trung Quốc phải không?"},{rawZh:"你喜欢喝茶吗？(Nǐ xǐhuan hē chá ma?)",zh:"你喜欢喝茶吗？",pinyin:"Nǐ xǐhuan hē chá ma?",vi:"Bạn có thích uống trà không?"}],tables:null,exercises:null}]},{lessonId:4,lessonKey:"Bài 4",lessonTitleZh:"我有两个孩子",lessonTitleFull:"Bài 4: 我有两个孩子",grammarPoints:[{id:"hsk1_b4_g1",num:1,title:"Câu chữ “有”",explanation:'“有” (yǒu) nghĩa là "có", biểu thị sự sở hữu. Phủ định bắt buộc dùng “没有” (méiyǒu), tuyệt đối không dùng "不有".',formula:"S + (没)有 + O",note:null,examples:[{rawZh:"我有两个孩子。(Wǒ yǒu liǎng gè háizi.)",zh:"我有两个孩子。",pinyin:"Wǒ yǒu liǎng gè háizi.",vi:"Tôi có hai đứa con."},{rawZh:"我没有姐姐。(Wǒ méiyǒu jiějie.)",zh:"我没有姐姐。",pinyin:"Wǒ méiyǒu jiějie.",vi:"Tôi không có chị gái."}],tables:null,exercises:null},{id:"hsk1_b4_g2",num:2,title:"Đại từ nghi vấn “几” và “多少”",explanation:`“几” (jǐ - mấy) dùng để hỏi số lượng nhỏ (thường dưới 10), bắt buộc phải có lượng từ đi kèm.
“多少” (duōshao - bao nhiêu) dùng để hỏi số lượng lớn (thường trên 10 hoặc không giới hạn), lượng từ có thể có hoặc không.`,formula:`几 + Lượng từ + Danh từ? 
多少 + (Lượng từ) + Danh từ?`,note:null,examples:[{rawZh:"你有几个苹果？(Nǐ yǒu jǐ gè píngguǒ?)",zh:"你有几个苹果？",pinyin:"Nǐ yǒu jǐ gè píngguǒ?",vi:"Bạn có mấy quả táo?"},{rawZh:"你们学校有多少个学生？(Nǐmen xuéxiào yǒu duōshao gè xuésheng?)",zh:"你们学校有多少个学生？",pinyin:"Nǐmen xuéxiào yǒu duōshao gè xuésheng?",vi:"Trường các bạn có bao nhiêu học sinh?"}],tables:[{title:"Bảng cách đọc và viết số từ 0 - 99",headers:["Số","Chữ Hán","Pinyin","Nghĩa","Số","Chữ Hán","Pinyin","Nghĩa"],rows:[["0","零","líng","không","20","二十","èrshí","hai mươi"],["1","一","yī","một","21","二十一","èrshíyī","hai mươi mốt"],["2","二","èr","hai","22","二十二","èrshíèr","hai mươi hai"],["3","三","sān","ba","30","三十","sānshí","ba mươi"],["4","四","sì","bốn","40","四十","sìshí","bốn mươi"],["5","五","wǔ","năm","50","五十","wǔshí","năm mươi"],["6","六","liù","sáu","60","六十","liùshí","sáu mươi"],["7","七","qī","bảy","70","七十","qīshí","bảy mươi"],["8","八","bā","tám","80","八十","bāshí","tám mươi"],["9","九","jiǔ","chín","90","九十","jiǔshí","chín mươi"],["10","十","shí","mười","99","九十九","jiǔshíjiǔ","chín mươi chín"]]}],exercises:[{prompt:"Bài tập 1: Điền số thích hợp: 3 + 4 = ?",answer:"三加四等于七 (Sān jiā sì děngyú qī)"},{prompt:"Bài tập 2: Điền số thích hợp: 10 + 5 = ?",answer:"十加五等于十五 (Shí jiā wǔ děngyú shíwǔ)"},{prompt:"Bài tập 3: Hỏi số lượng nhỏ hơn 10: Bạn có mấy quyển sách?",answer:"你有几本书？ (Nǐ yǒu jǐ běn shū?)"},{prompt:"Bài tập 4: Hỏi số lượng lớn: Lớp bạn có bao nhiêu người?",answer:"你们班有多少人？ (Nǐmen bān yǒu duōshao rén?)"}]},{id:"hsk1_b4_g3",num:3,title:"Trợ từ nghi vấn “呢” (1)",explanation:'Trợ từ 呢 (ne) dùng để hỏi ngược lại về đối tượng/tình huống đã được nhắc đến trước đó. Ý nghĩa: "Còn... thì sao?" / "Thế còn... thế nào?".',formula:"[Đối tượng/Sự vật] + 呢?",note:null,examples:[{rawZh:"我是老师，你呢？(Wǒ shì lǎoshī, nǐ ne?)",zh:"我是老师，你呢？",pinyin:"Wǒ shì lǎoshī, nǐ ne?",vi:"Tôi là giáo viên, còn bạn thì sao?"},{rawZh:"我是越南人，你呢？(Wǒ shì Yuènán rén, nǐ ne?)",zh:"我是越南人，你呢？",pinyin:"Wǒ shì Yuènán rén, nǐ ne?",vi:"Tôi là người Việt Nam, còn bạn thì sao?"}],tables:null,exercises:null},{id:"hsk1_b4_g4",num:4,title:"Danh lượng từ và cấu trúc danh lượng",explanation:"Nguyên tắc: Khi muốn chỉ số lượng của sự vật, bạn bắt buộc phải dùng lượng từ đứng giữa số từ và danh từ. Không được bỏ qua lượng từ.",formula:"Số từ + Lượng từ + Danh từ",note:"Mỗi danh từ thường đi với một lượng từ riêng. Nếu chưa rõ lượng từ, bạn có thể dùng 个 (gè) – đây là lượng từ phổ biến nhất, dùng được cho người và nhiều vật dụng khác.",examples:[{rawZh:"三个人 (sān gè rén)",zh:"三个人",pinyin:"sān gè rén",vi:"Ba người"},{rawZh:"一本书 (yī běn shū)",zh:"一本书",pinyin:"yī běn shū",vi:"Một quyển sách"},{rawZh:"两个学生 (liǎng gè xuésheng)",zh:"两个学生",pinyin:"liǎng gè xuésheng",vi:"Hai bạn học sinh"},{rawZh:"四口人 (sì kǒu rén)",zh:"四口人",pinyin:"sì kǒu rén",vi:"Bốn người (thường dùng chỉ nhân khẩu gia đình)"}],tables:null,exercises:null}]},{lessonId:5,lessonKey:"Bài 5",lessonTitleZh:"今天我休息",lessonTitleFull:"Bài 5: 今天我休息",grammarPoints:[{id:"hsk1_b5_g1",num:1,title:"Cách diễn đạt thời gian (1)",explanation:"Công thức diễn đạt Năm - Tháng - Ngày - Thứ trong tiếng Trung.",formula:"[Năm]年 (nián) + [Tháng]月 (yuè) + [Ngày]日/号 (rì/hào) + [Thứ]星期 (xīngqī)",note:"Tiếng Trung sắp xếp theo thứ tự từ lớn đến bé (Năm -> Tháng -> Ngày -> Thứ). Năm được đọc tách từng chữ số một.",examples:[{rawZh:"2026年8月2日，星期日 (èr líng èr liù nián bā yuè èr rì, xīngqī rì)",zh:"2026年8月2日，星期日",pinyin:"èr líng èr liù nián bā yuè èr rì, xīngqī rì",vi:"Chủ nhật, ngày 2 tháng 8 năm 2026."},{rawZh:"5月15日，星期二 (wǔ yuè shí wǔ rì, xīngqī èr)",zh:"5月15日，星期二",pinyin:"wǔ yuè shí wǔ rì, xīngqī èr",vi:"Thứ 3, ngày 15 tháng 5."}],tables:null,exercises:null},{id:"hsk1_b5_g2",num:2,title:"Câu vị ngữ danh từ",explanation:'Khái niệm: Là loại câu dùng danh từ hoặc cụm danh từ làm vị ngữ để miêu tả, không cần dùng động từ "是". Ứng dụng: Thường dùng để chỉ thời gian, ngày tháng, thời tiết, tuổi tác, giá cả.',formula:"S + N (Danh từ)",note:null,examples:[{rawZh:"今天星期日。(Jīntiān xīngqī rì.)",zh:"今天星期日。",pinyin:"Jīntiān xīngqī rì.",vi:"Hôm nay là Chủ nhật."},{rawZh:"今天八月三号。(Jīntiān bā yuè sān hào.)",zh:"今天八月三号。",pinyin:"Jīntiān bā yuè sān hào.",vi:"Hôm nay là ngày 3 tháng 8."},{rawZh:"我二十岁。(Wǒ èrshí suì.)",zh:"我二十岁。",pinyin:"Wǒ èrshí suì.",vi:"Tôi 20 tuổi."}],tables:null,exercises:null},{id:"hsk1_b5_g3",num:3,title:"Động từ năng nguyện “会”",explanation:"“会” (huì) biểu thị khả năng hoặc kỹ năng làm được việc gì đó thông qua quá trình học tập hoặc rèn luyện (biết làm gì).",formula:`Khẳng định: S + 会 + V + O 
Phủ định: S + 不会 + V + O 
Nghi vấn: S + 会 + V + O + 吗?`,note:null,examples:[{rawZh:"我会说中文。(Wǒ huì shuō Zhōngwén.)",zh:"我会说中文。",pinyin:"Wǒ huì shuō Zhōngwén.",vi:"Tôi biết nói tiếng Trung."},{rawZh:"他不会开车。(Tā bù huì kāichē.)",zh:"他不会开车。",pinyin:"Tā bù huì kāichē.",vi:"Anh ấy không biết lái xe."},{rawZh:"你会做饭吗？(Nǐ huì zuòfàn ma?)",zh:"你会做饭吗？",pinyin:"Nǐ huì zuòfàn ma?",vi:"Bạn có biết nấu ăn không?"}],tables:null,exercises:null}]},{lessonId:6,lessonKey:"Bài 6",lessonTitleZh:"你的手机号是多少?",lessonTitleFull:"Bài 6: 你的手机号是多少?",grammarPoints:[{id:"hsk1_b6_g1",num:1,title:"Động từ năng nguyện “想”",explanation:"“想” (xiǎng) biểu thị mong muốn, ý định hoặc dự định làm một việc gì đó (muốn / nghĩ / nhớ).",formula:`Khẳng định: S + 想 + V + O 
Phủ định: S + 不想 + V + O 
Nghi vấn: S + 想 + V + O + 吗? / S + 想 + V + 什么?`,note:null,examples:[{rawZh:"我想去超市。(Wǒ xiǎng qù chāoshì.)",zh:"我想去超市。",pinyin:"Wǒ xiǎng qù chāoshì.",vi:"Tôi muốn đi siêu thị."},{rawZh:"妈妈不想买电脑。(Māma bù xiǎng mǎi diànnǎo.)",zh:"妈妈不想买电脑。",pinyin:"Māma bù xiǎng mǎi diànnǎo.",vi:"Mẹ không muốn mua máy tính."},{rawZh:"你想吃什么？(Nǐ xiǎng chī shénme?)",zh:"你想吃什么？",pinyin:"Nǐ xiǎng chī shénme?",vi:"Bạn muốn ăn cái gì?"}],tables:null,exercises:null},{id:"hsk1_b6_g2",num:2,title:"Câu liên động (1)",explanation:"Câu liên động là câu có từ hai động từ trở lên cùng đi với một chủ ngữ, biểu thị mục đích (đi đâu để làm gì) hoặc phương thức thực hiện hành động.",formula:`1. Chỉ mục đích: S + 去/来 + [Địa điểm] + V2 + O 
2. Chỉ phương thức: S + [Phương tiện/Cách thức] + V2 + [Địa điểm]`,note:"Trong câu liên động, các hành động diễn ra theo trình tự thời gian: Hành động 1 xảy ra trước (di chuyển hoặc cách thức), Hành động 2 xảy ra sau (mục đích).",examples:[{rawZh:"我去超市买东西。(Wǒ qù chāoshì mǎi dōngxi.)",zh:"我去超市买东西。",pinyin:"Wǒ qù chāoshì mǎi dōngxi.",vi:"Tôi đi siêu thị mua đồ."},{rawZh:"他来学校学习。(Tā lái xuéxiào xuéxí.)",zh:"他来学校学习。",pinyin:"Tā lái xuéxiào xuéxí.",vi:"Anh ấy đến trường học tập."},{rawZh:"我坐出租车去医院。(Wǒ zuò chūzūchē qù yīyuàn.)",zh:"我坐出租车去医院。",pinyin:"Wǒ zuò chūzūchē qù yīyuàn.",vi:"Tôi đi taxi đến bệnh viện."},{rawZh:"他开车去超市。(Tā kāichē qù chāoshì.)",zh:"他开车去超市。",pinyin:"Tā kāichē qù chāoshì.",vi:"Anh ấy lái xe đi siêu thị."}],tables:null,exercises:null},{id:"hsk1_b6_g3",num:3,title:"Đại từ nghi vấn “怎么”",explanation:"“怎么” (zěnme) dùng để hỏi về cách thức hoặc phương thức thực hiện hành động (Làm thế nào? Bằng cách nào? Đi như thế nào?).",formula:"S + 怎么 + V + O?",note:null,examples:[{rawZh:"你怎么去学校？(Nǐ zěnme qù xuéxiào?)",zh:"你怎么去学校？",pinyin:"Nǐ zěnme qù xuéxiào?",vi:"Bạn đi đến trường bằng cách nào?"},{rawZh:"你怎么去超市？(Nǐ zěnme qù chāoshì?)",zh:"你怎么去超市？",pinyin:"Nǐ zěnme qù chāoshì?",vi:"Bạn đi siêu thị bằng cách nào?"},{rawZh:"这个电脑怎么买？(Zhège diànnǎo zěnme mǎi?)",zh:"这个电脑怎么买？",pinyin:"Zhège diànnǎo zěnme mǎi?",vi:"Máy tính này mua như thế nào?"}],tables:null,exercises:null}]},{lessonId:7,lessonKey:"Bài 7",lessonTitleZh:"我晚上六点半下班",lessonTitleFull:"Bài 7: 我晚上六点半下班",grammarPoints:[{id:"hsk1_b7_g1",num:1,title:"Cách diễn đạt thời gian (2)",explanation:`a. Sử dụng 点 (giờ) và 分 (phút) để diễn tả thời điểm cụ thể.
b. Sử dụng các danh từ chỉ thời gian như 上午, 中午, 下午, 晚上 để diễn tả khoảng thời gian trong ngày làm trạng ngữ chỉ thời gian.`,formula:"[Số giờ] + 点 + [Số phút] + 分",note:"30 phút thường dùng 半 (bàn - rưỡi) thay cho 30 分. Nếu số phút nhỏ hơn 10 (từ 1-9), bắt buộc phải có chữ 零 (líng) ở giữa.",examples:[{rawZh:"六点半 (liù diǎn bàn)",zh:"六点半",pinyin:"liù diǎn bàn",vi:"6 giờ rưỡi (6:30)"},{rawZh:"八点零五分 (bā diǎn líng wǔ fēn)",zh:"八点零五分",pinyin:"bā diǎn líng wǔ fēn",vi:"8 giờ 5 phút (8:05)"},{rawZh:"晚上八点我下班。(Wǎnshang bā diǎn wǒ xiàbān.)",zh:"晚上八点我下班。",pinyin:"Wǎnshang bā diǎn wǒ xiàbān.",vi:"8 giờ tối tôi tan làm."},{rawZh:"我下午去看电影。(Wǒ xiàwǔ qù kàn diànyǐng.)",zh:"我下午去看电影。",pinyin:"Wǒ xiàwǔ qù kàn diànyǐng.",vi:"Chiều nay tôi đi xem phim."}],tables:null,exercises:null},{id:"hsk1_b7_g2",num:2,title:"Trợ từ ngữ khí “吧” (1)",explanation:"Đặt ở cuối câu để biểu thị ý đề nghị, gợi ý, khuyên nhủ hoặc yêu cầu người nghe cùng thực hiện hành động (dịch là: nhé, nhỉ, đi, thôi).",formula:"S + V + O + 吧",note:null,examples:[{rawZh:"我们去超市吧。(Wǒmen qù chāoshì ba.)",zh:"我们去超市吧。",pinyin:"Wǒmen qù chāoshì ba.",vi:"Chúng ta đi siêu thị nhé."},{rawZh:"明天我们去书店吧。(Míngtiān wǒmen qù shūdiàn ba.)",zh:"明天我们去书店吧。",pinyin:"Míngtiān wǒmen qù shūdiàn ba.",vi:"Ngày mai chúng ta đi nhà sách nhé."},{rawZh:"我们吃饭吧。(Wǒmen chīfàn ba.)",zh:"我们吃饭吧。",pinyin:"Wǒmen chīfàn ba.",vi:"Chúng ta ăn cơm thôi/đi."}],tables:null,exercises:null},{id:"hsk1_b7_g3",num:3,title:"Vị trí của phó từ, từ ngữ chỉ thời gian khi làm trạng ngữ",explanation:`1. Phó từ (不, 很, 也) luôn đứng trước động từ hoặc tính từ.
2. Trạng ngữ chỉ thời gian (昨天, 今天, 明天) có thể đứng trước hoặc sau chủ ngữ, tuyệt đối không đặt ở cuối câu.`,formula:`1. S + Phó từ + V / Adj 
2. (Thời gian) + S + (Thời gian) + V + O`,note:"Nếu trong câu có cả trạng ngữ thời gian và trạng ngữ địa điểm, trật tự ưu tiên là: Thời gian + Địa điểm + Động từ.",examples:[{rawZh:"他不喜欢包子。(Tā bù xǐhuan bāozi.)",zh:"他不喜欢包子。",pinyin:"Tā bù xǐhuan bāozi.",vi:"Anh ấy không thích bánh bao."},{rawZh:"苹果很好。(Píngguǒ hěn hǎo.)",zh:"苹果很好。",pinyin:"Píngguǒ hěn hǎo.",vi:"Táo rất ngon."},{rawZh:"我也想去。(Wǒ yě xiǎng qù.)",zh:"我也想去。",pinyin:"Wǒ yě xiǎng qù.",vi:"Tôi cũng muốn đi."},{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"今天我去超市。(Jīntiān wǒ qù chāoshì.)",zh:"今天我去超市。",pinyin:"Jīntiān wǒ qù chāoshì.",vi:"Hôm nay tôi đi siêu thị."},{rawZh:"明天我买手机。(Míngtiān wǒ mǎi shǒujī.)",zh:"明天我买手机。",pinyin:"Míngtiān wǒ mǎi shǒujī.",vi:"Ngày mai tôi mua điện thoại."}],tables:null,exercises:null},{id:"hsk1_b7_g4",num:4,title:"Trợ từ ngữ khí “呢” (2)",explanation:"Dùng ở cuối câu trần thuật để biểu thị một sự thực đã được xác nhận, nhấn mạnh thông tin mà người nói đưa ra là một thực tế hiển nhiên.",formula:"S + V + ... + 呢",note:null,examples:[{rawZh:"我明天下午两点还上课呢。(Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.)",zh:"我明天下午两点还上课呢。",pinyin:"Wǒ míngtiān xiàwǔ liǎng diǎn hái shàngkè ne.",vi:"Chiều mai 2 giờ tôi vẫn còn phải đi học đấy."},{rawZh:"妹妹会做六七个菜呢。(Mèimei huì zuò liù qī gè cài ne.)",zh:"妹妹会做六七个菜呢。",pinyin:"Mèimei huì zuò liù qī gè cài ne.",vi:"Em gái còn biết nấu 6-7 món nữa đấy."}],tables:null,exercises:null}]},{lessonId:8,lessonKey:"Bài 8",lessonTitleZh:"我爸爸也在医院工作",lessonTitleFull:"Bài 8: 我爸爸也在医院工作",grammarPoints:[{id:"hsk1_b8_g1",num:1,title:"Phương vị từ (上, 下, 里, 前, 后)",explanation:"Phương vị từ là từ chỉ vị trí, phương hướng. Khi kết hợp với danh từ chỉ sự vật/địa điểm, phương vị từ luôn đứng SAU danh từ để tạo thành cụm từ chỉ vị trí nơi chốn.",formula:"Danh từ + Phương vị từ (上 / 下 / 里 / 前 / 后)",note:null,examples:[{rawZh:"桌子上 (zhuōzi shang)",zh:"桌子上",pinyin:"zhuōzi shang",vi:"Trên bàn (桌子: cái bàn + 上: trên)"},{rawZh:"房间里 (fángjiān lǐ)",zh:"房间里",pinyin:"fángjiān lǐ",vi:"Trong phòng (房间: căn phòng + 里: trong)"},{rawZh:"超市前 (chāoshì qián)",zh:"超市前",pinyin:"chāoshì qián",vi:"Trước siêu thị (超市: siêu thị + 前: trước)"},{rawZh:"椅子下 (yǐzi xià)",zh:"椅子下",pinyin:"yǐzi xià",vi:"Dưới ghế (椅子: cái ghế + 下: dưới)"}],tables:null,exercises:null},{id:"hsk1_b8_g2",num:2,title:"Giới từ “在”",explanation:"Giới từ “在” (zài) dùng để chỉ vị trí, nơi chốn của người, sự vật hoặc nơi diễn ra hành động (ở / tại).",formula:"S + 在 + Địa điểm + V + O",note:null,examples:[{rawZh:"他在学校。(Tā zài xuéxiào.)",zh:"他在学校。",pinyin:"Tā zài xuéxiào.",vi:"Anh ấy ở trường."},{rawZh:"我不在家。(Wǒ bú zài jiā.)",zh:"我不在家。",pinyin:"Wǒ bú zài jiā.",vi:"Tôi không ở nhà."},{rawZh:"我在房间里看电影。(Wǒ zài fángjiān lǐ kàn diànyǐng.)",zh:"我在房间里看电影。",pinyin:"Wǒ zài fángjiān lǐ kàn diànyǐng.",vi:"Tôi xem phim ở trong phòng."},{rawZh:"我昨天在学校学习。(Wǒ zuótiān zài xuéxiào xuéxí.)",zh:"我昨天在学校学习。",pinyin:"Wǒ zuótiān zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"他在医院工作。(Tā zài yīyuàn gōngzuò.)",zh:"他在医院工作。",pinyin:"Tā zài yīyuàn gōngzuò.",vi:"Anh ấy làm việc ở bệnh viện."}],tables:null,exercises:null},{id:"hsk1_b8_g3",num:3,title:"Động từ năng nguyện “能”",explanation:"“能” (néng - có thể) dùng để biểu thị năng lực, điều kiện khách quan hoặc sự cho phép làm một việc gì đó.",formula:`Khẳng định: S + 能 + V + O 
Phủ định: S + 不能 + V + O 
Nghi vấn: S + 能 + V + O + 吗?`,note:null,examples:[{rawZh:"我明天能去超市。(Wǒ míngtiān néng qù chāoshì.)",zh:"我明天能去超市。",pinyin:"Wǒ míngtiān néng qù chāoshì.",vi:"Ngày mai tôi có thể đi siêu thị."},{rawZh:"我能问你一个问题吗？(Wǒ néng wèn nǐ yīgè wèntí ma?)",zh:"我能问你一个问题吗？",pinyin:"Wǒ néng wèn nǐ yīgè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi không?"},{rawZh:"你不能在这里看电影。(Nǐ bù néng zài zhèlǐ kàn diànyǐng.)",zh:"你不能在这里看电影。",pinyin:"Nǐ bù néng zài zhèlǐ kàn diànyǐng.",vi:"Bạn không thể/không được xem phim ở đây."}],tables:null,exercises:null}]},{lessonId:9,lessonKey:"Bài 9",lessonTitleZh:"我明天上午在学校学习",lessonTitleFull:"Bài 9: 我明天上午在学校学习",grammarPoints:[{id:"hsk1_b9_g1",num:1,title:"Câu tồn hiện (1)",explanation:`a. Câu tồn hiện với “有” (yǒu) - Biểu thị sự tồn tại: Tại một địa điểm có người hoặc vật nào đó.
b. Câu tồn hiện với “是” (shì) - Biểu thị sự xác định: Khẳng định vật/người nằm ở vị trí đó chính là đối tượng được nhắc đến.`,formula:`a. [Địa điểm] + 有 + [Số lượng/Lượng từ] + [Danh từ] 
b. [Địa điểm] + 是 + [Danh từ]`,note:null,examples:[{rawZh:"房间里有一只小猫。(Fángjiān lǐ yǒu yì zhī xiǎo māo.)",zh:"房间里有一只小猫。",pinyin:"Fángjiān lǐ yǒu yì zhī xiǎo māo.",vi:"Trong phòng có một con mèo nhỏ."},{rawZh:"超市前有一家电影院。(Chāoshì qián yǒu yì jiā diànyǐngyuàn.)",zh:"超市前有一家电影院。",pinyin:"Chāoshì qián yǒu yì jiā diànyǐngyuàn.",vi:"Trước siêu thị có một rạp chiếu phim."},{rawZh:"医院里有很多病人。(Yīyuàn lǐ yǒu hěn duō bìngrén.)",zh:"医院里有很多病人。",pinyin:"Yīyuàn lǐ yǒu hěn duō bìngrén.",vi:"Trong bệnh viện có rất nhiều bệnh nhân."},{rawZh:"桌子上有一本书。(Zhuōzi shàng yǒu yì běn shū.)",zh:"桌子上有一本书。",pinyin:"Zhuōzi shàng yǒu yì běn shū.",vi:"Trên bàn có một quyển sách."},{rawZh:"前边是学校。(Qiánbian shì xuéxiào.)",zh:"前边是学校。",pinyin:"Qiánbian shì xuéxiào.",vi:"Phía trước là trường học."},{rawZh:"超市前是我的家。(Chāoshì qián shì wǒ de jiā.)",zh:"超市前是我的家。",pinyin:"Chāoshì qián shì wǒ de jiā.",vi:"Trước siêu thị là nhà tôi."},{rawZh:"那儿是我的房间。(Nàr shì wǒ de fángjiān.)",zh:"那儿是我的房间。",pinyin:"Nàr shì wǒ de fángjiān.",vi:"Chỗ kia là phòng của tôi."}],tables:null,exercises:null},{id:"hsk1_b9_g2",num:2,title:"Trật tự của từ ngữ chỉ thời gian và nơi chốn khi cùng làm trạng ngữ",explanation:"Trong tiếng Trung, khi trong câu xuất hiện cả trạng ngữ chỉ thời gian và trạng ngữ chỉ địa điểm, trật tự ưu tiên luôn tuân theo quy tắc: Thời gian đứng trước địa điểm.",formula:"[Thời gian] + [Địa điểm] + [Động từ] + [Tân ngữ]",note:"Thời gian có thể đứng trước hoặc sau Chủ ngữ.",examples:[{rawZh:"昨天我在学校学习。(Zuótiān wǒ zài xuéxiào xuéxí.)",zh:"昨天我在学校学习。",pinyin:"Zuótiān wǒ zài xuéxiào xuéxí.",vi:"Hôm qua tôi học ở trường."},{rawZh:"明天我去超市。(Míngtiān wǒ qù chāoshì.)",zh:"明天我去超市。",pinyin:"Míngtiān wǒ qù chāoshì.",vi:"Ngày mai tôi đi siêu thị."},{rawZh:"我晚上八点在医院下班。(Wǒ wǎnshang bā diǎn zài yīyuàn xiàbān.)",zh:"我晚上八点在医院下班。",pinyin:"Wǒ wǎnshang bā diǎn zài yīyuàn xiàbān.",vi:"Tối nay 8 giờ tôi tan làm ở bệnh viện."}],tables:null,exercises:null},{id:"hsk1_b9_g3",num:3,title:"“第” dùng để biểu thị số thứ tự",explanation:"“第” (dì) được dùng để tạo thành số thứ tự, giúp xác định thứ tự, vị trí hoặc cấp bậc (ví dụ: thứ nhất, thứ hai, bài một, bài hai...).",formula:"第 (dì) + Số từ + (Lượng từ) + Danh từ",note:null,examples:[{rawZh:"第一课 (Dì yī kè)",zh:"第一课",pinyin:"Dì yī kè",vi:"Bài học số 1 (Bài 1)."},{rawZh:"第二楼 (Dì èr lóu)",zh:"第二楼",pinyin:"Dì èr lóu",vi:"Tầng 2."},{rawZh:"第三个 (Dì sān gè)",zh:"第三个",pinyin:"Dì sān gè",vi:"Cái thứ 3."}],tables:null,exercises:null}]},{lessonId:10,lessonKey:"Bài 10",lessonTitleZh:"这儿的苹果真便宜！",lessonTitleFull:"Bài 10: 这儿的苹果真便宜！",grammarPoints:[{id:"hsk1_b10_g1",num:1,title:"Cách diễn đạt số tiền",explanation:`Trong tiếng Trung, khẩu ngữ dùng 块 (kuài - đồng), 毛 (máo - hào), 分 (fēn - xu). Văn viết dùng 元 (yuán), 角 (jiǎo), 分 (fēn).
Quy tắc quy đổi: 1 块 (kuài) = 10 毛 (máo), 1 毛 (máo) = 10 分 (fēn).`,formula:`Cách diễn đạt: 
1. Đơn vị đồng: [Số] + 块 
2. Có số lẻ: [Số] + 块 + [Số] + (毛) 
3. Đầy đủ: [Số] + 块 + [Số] + 毛 + [Số] + 分 
4. Có số 0 ở giữa: thêm 零 (líng)`,note:null,examples:[{rawZh:"3块 (Sān kuài)",zh:"3块",pinyin:"Sān kuài",vi:"3 tệ"},{rawZh:"1块5 (Yī kuài wǔ)",zh:"1块5",pinyin:"Yī kuài wǔ",vi:"1.5 tệ (1 đồng 5 hào)"},{rawZh:"1块5毛5 (Yī kuài wǔ máo wǔ fēn)",zh:"1块5毛5",pinyin:"Yī kuài wǔ máo wǔ fēn",vi:"1.55 tệ (1 đồng 5 hào 5 xu)"},{rawZh:"1块零5分 (Yī kuài líng wǔ fēn)",zh:"1块零5分",pinyin:"Yī kuài líng wǔ fēn",vi:"1.05 tệ (1 đồng 0 hào 5 xu)"}],tables:null,exercises:null},{id:"hsk1_b10_g2",num:2,title:"Câu vị ngữ tính từ",explanation:'Tính từ có thể trực tiếp làm vị ngữ trong câu. Trước tính từ khẳng định thường thêm phó từ chỉ mức độ (很, 真, 非常). Phủ định dùng "不".',formula:`Khẳng định: Chủ ngữ + (很/真/非常) + Tính từ 
Phủ định: Chủ ngữ + 不 + Tính từ 
Nghi vấn: Chủ ngữ + Tính từ + 吗?`,note:null,examples:[{rawZh:"那个苹果很好吃。(Nàgè píngguǒ hěn hǎochī.)",zh:"那个苹果很好吃。",pinyin:"Nàgè píngguǒ hěn hǎochī.",vi:"Quả táo đó rất ngon."},{rawZh:"我不忙。(Wǒ bù máng.)",zh:"我不忙。",pinyin:"Wǒ bù máng.",vi:"Tôi không bận."},{rawZh:"你忙吗？(Nǐ máng ma?)",zh:"你忙吗？",pinyin:"Nǐ máng ma?",vi:"Bạn có bận không?"}],tables:null,exercises:null},{id:"hsk1_b10_g3",num:3,title:"Đại từ nghi vấn “怎么样”",explanation:"Đại từ nghi vấn “怎么样” (zěnmeyàng) thường đặt ở cuối câu dùng để hỏi về trạng thái, tính chất của sự vật, tình hình sức khỏe/công việc, hoặc dùng để đưa ra lời gợi ý, hỏi ý kiến (thế nào? được không?).",formula:`S + 怎么样? 
Câu đề nghị + 怎么样?`,note:null,examples:[{rawZh:"这个杯子怎么样？(Zhège bēizi zěnmeyàng?)",zh:"这个杯子怎么样？",pinyin:"Zhège bēizi zěnmeyàng?",vi:"Cái cốc này thế nào?"},{rawZh:"这件衣服怎么样？(Zhè jiàn yīfu zěnmeyàng?)",zh:"这件衣服怎么样？",pinyin:"Zhè jiàn yīfu zěnmeyàng?",vi:"Bộ quần áo này thế nào?"},{rawZh:"我们去看电影，怎么样？(Wǒmen qù kàn diànyǐng, zěnmeyàng?)",zh:"我们去看电影，怎么样？",pinyin:"Wǒmen qù kàn diànyǐng, zěnmeyàng?",vi:"Chúng ta đi xem phim nhé, được không?"}],tables:null,exercises:null}]},{lessonId:11,lessonKey:"Bài 11",lessonTitleZh:"我读大学了",lessonTitleFull:"Bài 11: 我读大学了",grammarPoints:[{id:"hsk1_b11_g1",num:1,title:"Câu hỏi chính phản",explanation:"Câu hỏi chính phản dùng hình thức khẳng định đi kèm phủ định để hỏi lựa chọn Có/Không (Yes/No).",formula:`- Với động từ: S + V + 不/没 + V + (O)? 
- Với tính từ: S + Adj + 不 + Adj?`,note:'Khi dùng dạng câu hỏi chính phản, tuyệt đối không được dùng trợ từ "吗" ở cuối câu.',examples:[{rawZh:"你想不想去超市？(Nǐ xiǎng bu xiǎng qù chāoshì?)",zh:"你想不想去超市？",pinyin:"Nǐ xiǎng bu xiǎng qù chāoshì?",vi:"Bạn có muốn đi siêu thị không?"},{rawZh:"你去没去学校？(Nǐ qù mei qù xuéxiào?)",zh:"你去没去学校？",pinyin:"Nǐ qù mei qù xuéxiào?",vi:"Bạn đã đi đến trường chưa?"},{rawZh:"这件衣服好看不好看？(Zhè jiàn yīfu hǎokàn bu hǎokàn?)",zh:"这件衣服好看不好看？",pinyin:"Zhè jiàn yīfu hǎokàn bu hǎokàn?",vi:"Bộ quần áo này có đẹp không?"}],tables:null,exercises:null},{id:"hsk1_b11_g2",num:2,title:"Phó từ chỉ thời gian “在/正在”",explanation:`Dùng để diễn tả hành động đang diễn ra tại thời điểm nói (đang...).
- 正在 (zhèngzài): Nhấn mạnh hành động đang diễn ra ngay lúc này.
- 在 (zài): Dùng để mô tả hành động đang xảy ra.
Phủ định bắt buộc dùng "没 / 没有", tuyệt đối không được dùng "不".`,formula:"S + (正在 / 在) + V + (O) + (呢)",note:'"呢" ở cuối câu thường được dùng trong khẩu ngữ để tăng tính tự nhiên, gần gũi.',examples:[{rawZh:"我正在做饭呢。(Wǒ zhèngzài zuòfàn ne.)",zh:"我正在做饭呢。",pinyin:"Wǒ zhèngzài zuòfàn ne.",vi:"Tôi đang nấu cơm đấy."},{rawZh:"他在看书。(Tā zài kànshū.)",zh:"他在看书。",pinyin:"Tā zài kànshū.",vi:"Anh ấy đang đọc sách."},{rawZh:"我没在睡觉。(Wǒ méi zài shuìjiào.)",zh:"我没在睡觉。",pinyin:"Wǒ méi zài shuìjiào.",vi:"Tôi không có đang ngủ."}],tables:null,exercises:null},{id:"hsk1_b11_g3",num:3,title:"Động từ năng nguyện “要”",explanation:"Động từ năng nguyện “要” (yào) trong tiếng Trung biểu thị mong muốn mạnh mẽ, quyết tâm, ý định hoặc kế hoạch chắc chắn sẽ thực hiện (sẽ / phải / muốn).",formula:"S + 要 + V + O",note:null,examples:[{rawZh:"他今天要和小朋友玩。(Tā jīntiān yào hé xiǎopéngyou wán.)",zh:"他今天要和小朋友玩。",pinyin:"Tā jīntiān yào hé xiǎopéngyou wán.",vi:"Hôm nay cậu ấy sẽ chơi cùng các bạn nhỏ."},{rawZh:"妈妈要去超市。(Māma yào qù chāoshì.)",zh:"妈妈要去超市。",pinyin:"Māma yào qù chāoshì.",vi:"Mẹ muốn/sắp đi siêu thị."}],tables:null,exercises:null}]},{lessonId:12,lessonKey:"Bài 12",lessonTitleZh:"昨天下雪了",lessonTitleFull:"Bài 12: 昨天下雪了",grammarPoints:[{id:"hsk1_b12_g1",num:1,title:"Câu phi chủ vị",explanation:"Câu phi chủ vị là câu không có cấu trúc chủ ngữ - vị ngữ rõ ràng, thường dùng để mô tả hiện tượng tự nhiên, thời tiết, hoặc các câu cảm thán/thúc giục ngắn gọn.",formula:"V + 了 / Tính từ / Thán từ!",note:null,examples:[{rawZh:"下雨了。(Xiàyǔ le.)",zh:"下雨了。",pinyin:"Xiàyǔ le.",vi:"Trời mưa rồi."},{rawZh:"下雪了。(Xiàxuě le.)",zh:"下雪了。",pinyin:"Xiàxuě le.",vi:"Trời đổ tuyết rồi."},{rawZh:"上课了。(Shàngkè le.)",zh:"上课了。",pinyin:"Shàngkè le.",vi:"Đến giờ vào lớp rồi."},{rawZh:"真漂亮！(Zhēn piàoliang!)",zh:"真漂亮！",pinyin:"Zhēn piàoliang!",vi:"Thật là đẹp!"}],tables:null,exercises:null},{id:"hsk1_b12_g2",num:2,title:"Trợ từ ngữ khí “了” (1)",explanation:`Trợ từ ngữ khí “了” (1) được dùng ở cuối câu để diễn tả sự thay đổi trạng thái hoặc một tình huống mới đã xuất hiện (rồi...).
Trong câu phủ định, bắt buộc dùng “没(有)” và phải bỏ “了”.`,formula:`1. Khẳng định: S + V + 了 
2. Phủ định: S + 没(有) + V`,note:null,examples:[{rawZh:"下雨了。(Xiàyǔ le.)",zh:"下雨了。",pinyin:"Xiàyǔ le.",vi:"Trời mưa rồi (trước đó không mưa)."},{rawZh:"我生病了。(Wǒ shēngbìng le.)",zh:"我生病了。",pinyin:"Wǒ shēngbìng le.",vi:"Tôi bị ốm rồi (trước đó khỏe)."},{rawZh:"我吃饭了。(Wǒ chīfàn le.)",zh:"我吃饭了。",pinyin:"Wǒ chīfàn le.",vi:"Tôi ăn cơm rồi."},{rawZh:"没下雨。(Méi xiàyǔ.)",zh:"没下雨。",pinyin:"Méi xiàyǔ.",vi:"Không mưa / Chưa mưa."},{rawZh:"我没吃饭。(Wǒ méi chīfàn.)",zh:"我没吃饭。",pinyin:"Wǒ méi chīfàn.",vi:"Tôi chưa ăn cơm."},{rawZh:"我没看电影。(Wǒ méi kàn diànyǐng.)",zh:"我没看电影。",pinyin:"Wǒ méi kàn diànyǐng.",vi:"Tôi không xem phim / Chưa xem phim."}],tables:null,exercises:null},{id:"hsk1_b12_g3",num:3,title:"Cấu trúc “太……了”",explanation:"Cấu trúc “太……了” (tài... le) dùng để biểu thị mức độ cực kỳ cao, thường dùng trong câu cảm thán để bày tỏ cảm xúc (quá / cực kỳ / lắm).",formula:"S + 太 + Tính từ + 了",note:null,examples:[{rawZh:"太好了！(Tài hǎo le!)",zh:"太好了！",pinyin:"Tài hǎo le!",vi:"Tốt quá! / Tuyệt vời quá!"},{rawZh:"太漂亮了！(Tài piàoliang le!)",zh:"太漂亮了！",pinyin:"Tài piàoliang le!",vi:"Đẹp quá!"},{rawZh:"太贵了！(Tài guì le!)",zh:"太贵了！",pinyin:"太贵了！",vi:"Đắt quá!"},{rawZh:"太冷了！(Tài lěng le!)",zh:"太冷了！",pinyin:"Tài lěng le!",vi:"Lạnh quá!"},{rawZh:"太好看了！(Tài hǎokàn le!)",zh:"太好看了！",pinyin:"Tài hǎokàn le!",vi:"Đẹp quá! / Hay quá!"}],tables:null,exercises:null}]},{lessonId:13,lessonKey:"Bài 13",lessonTitleZh:"请给我一杯茶",lessonTitleFull:"Bài 13: 请给我一杯茶",grammarPoints:[{id:"hsk1_b13_g1",num:1,title:"Động từ năng nguyện “可以”",explanation:'Động từ năng nguyện “可以” (kěyǐ) trong tiếng Trung có nghĩa là "có thể", dùng để biểu thị sự cho phép (được phép làm gì) hoặc khả năng (có thể làm việc gì).',formula:`- Khẳng định: S + 可以 + V + O 
- Phủ định: S + 不可以 + V + O 
- Nghi vấn: S + 可以 + V + O + 吗?`,note:null,examples:[{rawZh:"我可以问你一个问题吗？(Wǒ kěyǐ wèn nǐ yīgè wèntí ma?)",zh:"我可以问你一个问题吗？",pinyin:"Wǒ kěyǐ wèn nǐ yīgè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi được không?"},{rawZh:"我可以坐这儿吗？(Wǒ kěyǐ zuò zhèr ma?)",zh:"我可以坐这儿吗？",pinyin:"Wǒ kěyǐ zuò zhèr ma?",vi:"Tôi có thể ngồi ở đây được không?"},{rawZh:"这儿不可以睡觉。(Zhèr bù kěyǐ shuìjiào.)",zh:"这儿不可以睡觉。",pinyin:"Zhèr bù kěyǐ shuìjiào.",vi:"Ở đây không được phép ngủ."},{rawZh:"你可以给我打个电话。(Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.)",zh:"你可以给我打个电话。",pinyin:"Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.",vi:"Bạn có thể gọi điện thoại cho tôi."}],tables:null,exercises:null},{id:"hsk1_b13_g2",num:2,title:"Cấu trúc “Động từ + 一下”",explanation:'Cấu trúc "Động từ + 一下" (yíxià) dùng để làm mềm ngữ khí, khiến lời đề nghị hoặc yêu cầu trở nên nhẹ nhàng, lịch sự và tự nhiên hơn. Nó diễn tả việc thực hiện hành động trong thời gian ngắn hoặc "thử làm" điều gì đó.',formula:"Động từ + 一下",note:null,examples:[{rawZh:"你可以打电话问一下。(Nǐ kěyǐ dǎ diànhuà wèn yíxià.)",zh:"你可以打电话问一下。",pinyin:"Nǐ kěyǐ dǎ diànhuà wèn yíxià.",vi:"Bạn có thể gọi điện thoại hỏi một chút."},{rawZh:"请休息一下。(Qǐng xiūxi yíxià.)",zh:"请休息一下。",pinyin:"Qǐng xiūxi yíxià.",vi:"Xin hãy nghỉ ngơi một lát."},{rawZh:"你看一下。(Nǐ kàn yíxià.)",zh:"你看一下。",pinyin:"Nǐ kàn yíxià.",vi:"Bạn xem qua một chút đi."}],tables:null,exercises:null},{id:"hsk1_b13_g3",num:3,title:"Câu có hai tân ngữ (1)",explanation:`Câu có hai tân ngữ là loại câu mà động từ kết hợp với hai tân ngữ cùng lúc: một tân ngữ chỉ người (tân ngữ gián tiếp) và một tân ngữ chỉ vật/sự việc (tân ngữ trực tiếp).
a. Động từ "给" (gěi - đưa/cho)
b. Động từ "问" (wèn - hỏi)`,formula:`Chủ ngữ + Động từ + Tân ngữ chỉ người + Tân ngữ chỉ vật 
a. S + 给 + Người + Vật 
b. S + 问 + Người + Vật/Câu hỏi`,note:null,examples:[{rawZh:"请给我一杯茶。(Qǐng gěi wǒ yì bēi chá.)",zh:"请给我一杯茶。",pinyin:"Qǐng gěi wǒ yì bēi chá.",vi:"Xin hãy cho tôi một cốc trà."},{rawZh:"你可以给我打个电话。(Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.)",zh:"你可以给我打个电话。",pinyin:"Nǐ kěyǐ gěi wǒ dǎ gè diànhuà.",vi:"Bạn có thể gọi cho tôi một cuộc điện thoại."},{rawZh:"我可以问你一个问题吗？(Wǒ kěyǐ wèn nǐ yīgè wèntí ma?)",zh:"我可以问你一个问题吗？",pinyin:"Wǒ kěyǐ wèn nǐ yīgè wèntí ma?",vi:"Tôi có thể hỏi bạn một câu hỏi không?"}],tables:null,exercises:null}]},{lessonId:14,lessonKey:"Bài 14",lessonTitleZh:"我看了一个电影",lessonTitleFull:"Bài 14: 我看了一个电影",grammarPoints:[{id:"hsk1_b14_g1",num:1,title:"Trợ từ động thái “了” (2)",explanation:"Trợ từ động thái “了” (2) được đặt ngay sau động từ để biểu thị hành động đã xảy ra hoặc đã hoàn thành.",formula:`- Khẳng định: S + V + 了 + (O) 
- Phủ định: S + 没(有) + V + (O) 
- Nghi vấn: S + V + 了 + O + 吗? (Hoặc V + 了 + O + 没有?)`,note:`Bắt buộc bỏ "了" trong câu phủ định.
Phân biệt: 
- “了” (1) đứng cuối câu (Bài 12): Chỉ sự thay đổi trạng thái.
- “了” (2) đứng sau động từ (Bài 14): Chỉ hành động đã hoàn thành.`,examples:[{rawZh:"我看了一个电影。(Wǒ kàn le yīgè diànyǐng.)",zh:"我看了一个电影。",pinyin:"Wǒ kàn le yīgè diànyǐng.",vi:"Tôi đã xem một bộ phim."},{rawZh:"我买了新电脑。(Wǒ mǎi le xīn diànnǎo.)",zh:"我买了新电脑。",pinyin:"Wǒ mǎi le xīn diànnǎo.",vi:"Tôi đã mua máy tính mới."},{rawZh:"我没看电影。(Wǒ méi kàn diànyǐng.)",zh:"我没看电影。",pinyin:"Wǒ méi kàn diànyǐng.",vi:"Tôi không xem phim / Tôi chưa xem phim."}],tables:null,exercises:null},{id:"hsk1_b14_g2",num:2,title:"Từ ly hợp (离合词)",explanation:"Từ ly hợp (离合词) là những từ trong tiếng Trung có cấu tạo gồm 2 phần: Động từ (V) + Tân ngữ (O). Khi dùng với trợ từ (le, guo) hoặc số lượng/thời lượng, bắt buộc chèn vào giữa V và O.",formula:"Động từ + (Số lượng/Thời lượng/Trợ từ 了) + Tân ngữ",note:`Nguyên tắc quan trọng: 
1. Có thể tách rời để chèn thành phần bổ nghĩa vào giữa.
2. Không thêm tân ngữ trực tiếp phía sau vì bản thân từ đã chứa một tân ngữ.`,examples:[{rawZh:"睡了一觉 (shuì le yí jiào)",zh:"睡了一觉",pinyin:"shuì le yí jiào",vi:"Đã ngủ một giấc (睡觉: đi ngủ)"},{rawZh:"吃了一顿饭 (chī le yí dùn fàn)",zh:"吃了一顿饭",pinyin:"chī le yí dùn fàn",vi:"Đã ăn một bữa cơm (吃饭: ăn cơm)"},{rawZh:"打了个电话 (dǎ le gè diànhuà)",zh:"打了个电话",pinyin:"dǎ le gè diànhuà",vi:"Đã gọi một cuộc điện thoại (打电话: gọi điện thoại)"},{rawZh:"开了两小时车 (kāi le liǎng xiǎoshí chē)",zh:"开了两小时车",pinyin:"kāi le liǎng xiǎoshí chē",vi:"Đã lái xe 2 tiếng (开车: lái xe)"},{rawZh:"上了一节课 (shàng le yì jié kè)",zh:"上了一节课",pinyin:"shàng le yì jié kè",vi:"Đã lên một tiết học (上课: lên lớp)"},{rawZh:"下了班 (xià le bān)",zh:"下了班",pinyin:"xià le bān",vi:"Đã tan làm (下班: tan làm)"},{rawZh:"做了很多饭 (zuò le hěn duō fàn)",zh:"做了很多饭",pinyin:"zuò le hěn duō fàn",vi:"Đã nấu rất nhiều cơm (做饭: nấu cơm)"}],tables:null,exercises:null},{id:"hsk1_b14_g3",num:3,title:"Phó từ chỉ phạm vi “都”",explanation:"Phó từ “都” (dōu) có nghĩa là “đều”, dùng để tổng kết tất cả đối tượng trong câu. Vị trí: Luôn đứng sau chủ ngữ (ở dạng số nhiều) và đứng trước động từ/tính từ.",formula:`Khẳng định: Chủ ngữ (số nhiều) + 都 + Động từ/Tính từ 
Phủ định: Chủ ngữ (số nhiều) + 都 + 不 + Động từ/Tính từ`,note:"Chủ ngữ của “都” bắt buộc phải là số nhiều (ví dụ: 我们 - chúng tôi, 你们 - các bạn, 他们 - họ, hoặc A và B).",examples:[{rawZh:"我们都喜欢吃苹果。(Wǒmen dōu xǐhuan chī píngguǒ.)",zh:"我们都喜欢吃苹果。",pinyin:"Wǒmen dōu xǐhuan chī píngguǒ.",vi:"Chúng tôi đều thích ăn táo."},{rawZh:"他们都很忙。(Tāmen dōu hěn máng.)",zh:"他们都很忙。",pinyin:"Tāmen dōu hěn máng.",vi:"Họ đều rất bận."},{rawZh:"我们都不想去超市。(Wǒmen dōu bù xiǎng qù chāoshì.)",zh:"我们都不想去超市。",pinyin:"Wǒmen dōu bù xiǎng qù chāoshì.",vi:"Chúng tôi đều không muốn đi siêu thị."}],tables:null,exercises:null}]},{lessonId:15,lessonKey:"Bài 15",lessonTitleZh:"大兴机场见",lessonTitleFull:"Bài 15: 大兴机场见",grammarPoints:[{id:"hsk1_b15_g1",num:1,title:"Câu ghép đẳng lập “……，还/也……”",explanation:`Dùng để kết nối hai vế câu có cùng chủ ngữ, diễn tả việc vừa có tính chất/hành động này, lại vừa có tính chất/hành động kia.
- 也 (yě - cũng): Liệt kê các trạng thái hoặc hành động tương đồng.
- 还 (hái - còn/lại còn): Bổ sung thêm thông tin hoặc nhấn mạnh một khía cạnh khác.`,formula:"Chủ ngữ + V/Adj 1 + ..., (Chủ ngữ) + 还/也 + V/Adj 2",note:null,examples:[{rawZh:"他会做饭，也会开车。(Tā huì zuòfàn, yě huì kāichē.)",zh:"他会做饭，也会开车。",pinyin:"Tā huì zuòfàn, yě huì kāichē.",vi:"Anh ấy biết nấu ăn, cũng biết lái xe."},{rawZh:"这件衣服很好看，还很便宜。(Zhè jiàn yīfu hěn hǎokàn, hái hěn piányi.)",zh:"这件衣服很好看，还很便宜。",pinyin:"Zhè jiàn yīfu hěn hǎokàn, hái hěn piányi.",vi:"Bộ quần áo này rất đẹp, lại còn rất rẻ."}],tables:null,exercises:null}]}];typeof window<"u"&&(window.HSK1_STRUCTURED_GRAMMAR=n);export{n as H};
